{"path":"public/app.js","content":"'use strict';

const $ = (selector) => document.querySelector(selector);
let memberId = '';
let books = [];
let actionQueue = Promise.resolve();

async function request(url, options = {}) {
  const method = options.method || 'GET';
  const body = options.body || null;
  const headers = { 'content-type': 'application/json', ...(options.headers || {}) };
  const result = await new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open(method, url);
    Object.entries(headers).forEach(([name, value]) => xhr.setRequestHeader(name, value));
    xhr.onload = () => resolve({ status: xhr.status, text: xhr.responseText });
    xhr.onerror = () => reject(new Error('Network request failed'));
    xhr.send(body);
  });
  let data;
  try { data = JSON.parse(result.text); } catch { throw new Error(`Request failed (${result.status})`); }
  if (result.status < 200 || result.status >= 300) throw new Error(data.error || `Request failed (${result.status})`);
  return data;
}

function showMessage(text, kind = '') {
